-- Step 71: 43 new species profiles, plus 'Black Widow Tetra' as another name for Black Skirt Tetra.
--
-- Chosen after comparing the library with another site's 763-entry list: these are real
-- freshwater (and two brackish) aquarium species that were missing here. Left out on purpose:
-- saltwater and joke entries, fish that are illegal to keep in the US (Asian arowana,
-- snakeheads, walking catfish), placeholder names and monster fish.
--
-- Safe to run more than once: a species whose slug already exists is skipped.

insert into public.species (slug, common_name, scientific_name, also_known_as, former_names, trade_codes, group_name, family, genus, water_type, temp_min_f, temp_max_f, ph_min, ph_max, gh_min, gh_max, max_size_in, min_tank_gal, temperament, social, min_group_size, swim_level, diet, fin_nipper, plant_safe, care_level, suitability, breeding_type, lifespan, origin, summary, body, entry_type, described)
select v.slug, v.common_name, v.scientific_name, v.also_known_as, v.former_names, v.trade_codes, v.group_name, v.family, v.genus, v.water_type, v.temp_min_f, v.temp_max_f, v.ph_min, v.ph_max, v.gh_min, v.gh_max, v.max_size_in, v.min_tank_gal, v.temperament, v.social, v.min_group_size, v.swim_level, v.diet, v.fin_nipper, v.plant_safe, v.care_level, v.suitability, v.breeding_type, v.lifespan, v.origin, v.summary, v.body, v.entry_type, v.described
from (values
  ('yellow-phantom-tetra', 'Yellow Phantom Tetra', 'Hyphessobrycon roseus', array['Golden Phantom Tetra']::text[], '{}'::text[], '{}'::text[], 'Tetras & Characins', 'Characidae', 'Hyphessobrycon', 'Freshwater', 72, 79, 5.5, 7.0, 1, 10, 1.2, 10, 'Peaceful', 'Schooling', 8, 'Middle', 'Omnivore', false, true, 'Intermediate', 'Intermediate', 'Egg-scatterer', '3-5 years', 'Guyana, Suriname and French Guiana', 'A tiny golden phantom tetra with a red-tipped dorsal fin. Gentler and smaller than black or red phantoms.', 'Yellow phantoms are one of the smallest phantom tetras and far less pushy than their black and red cousins, so they suit nano and planted community tanks. They show their best gold color in soft, slightly acidic water with dark substrate, floating plants and a little tannin. Keep eight or more; males flare at each other in harmless displays. Offer small foods like crushed flake, micro pellets and baby brine shrimp.', 'species', true),
  ('jellybean-tetra', 'Jellybean Tetra', 'Lepidarchus adonis', array['Adonis Tetra', 'Jelly Bean Tetra']::text[], '{}'::text[], '{}'::text[], 'Tetras & Characins', 'Alestidae', 'Lepidarchus', 'Freshwater', 72, 79, 5.5, 6.8, 1, 6, 0.8, 10, 'Peaceful', 'Schooling', 8, 'Middle', 'Omnivore', false, true, 'Advanced', 'Intermediate', 'Egg-scatterer', '2-4 years', 'Coastal West Africa (Ghana, Sierra Leone, Ivory Coast)', 'One of the smallest tetras in the hobby: under an inch, nearly see-through, with a dotted pattern on males.', 'Jellybean tetras are a nano fish for keepers who can hold soft, acidic, very clean water. Their size means tankmates must be equally tiny and calm, such as small rasboras, pygmy corys or shrimp. A heavily planted tank with leaf litter and dim light keeps them confident. Feed very fine foods: baby brine shrimp, microworms and crushed flake. They don''t tolerate swings in water quality, so add them only to a mature tank.', 'species', true),
  ('hockeystick-pencilfish', 'Hockeystick Pencilfish', 'Nannostomus eques', array['Brown Pencilfish', 'Diptail Pencilfish', 'Tube-mouthed Pencilfish']::text[], array['Poecilobrycon eques']::text[], '{}'::text[], 'Tetras & Characins', 'Lebiasinidae', 'Nannostomus', 'Freshwater', 75, 82, 5.5, 7.0, 1, 10, 2.0, 15, 'Peaceful', 'Schooling', 6, 'Top', 'Omnivore', false, true, 'Intermediate', 'Intermediate', 'Egg-scatterer', '3-5 years', 'Amazon and Orinoco basins (Brazil, Colombia, Peru, Guyana)', 'A slim pencilfish that hangs just under the surface at a head-up angle, like a hockey stick.', 'Hockeystick pencilfish spend their time near the top, tilted at an angle among floating plants, which makes them a great fit for the upper layer of a quiet community tank. They have tiny mouths, so feed small foods that float or sink slowly: crushed flake, micro pellets, daphnia and baby brine shrimp. Keep six or more with other small, peaceful fish and give them cover at the surface. Soft, acidic water brings out the gold and black stripe.', 'species', true),
  ('one-lined-pencilfish', 'One-lined Pencilfish', 'Nannostomus unifasciatus', array['One-line Pencilfish', 'Oneline Pencilfish']::text[], '{}'::text[], '{}'::text[], 'Tetras & Characins', 'Lebiasinidae', 'Nannostomus', 'Freshwater', 75, 82, 5.5, 7.0, 1, 8, 2.4, 15, 'Peaceful', 'Schooling', 6, 'Mid-top', 'Omnivore', false, true, 'Intermediate', 'Intermediate', 'Egg-scatterer', '3-5 years', 'Amazon and Orinoco basins (Brazil, Colombia, Guyana)', 'A long, slender pencilfish with one bold black stripe and a red-and-white tail, swimming at a slight tilt.', 'One-lined pencilfish are gentle, slow-moving fish that swim on a slight angle through the middle and upper water. Males have a red patch in the tail fin edged in white. They''re shy, so keep them in a group of six or more with calm tankmates in a well-planted tank with floating cover and soft water. Small, varied foods keep them in condition; frozen daphnia and brine shrimp are favorites.', 'species', true),
  ('elegant-cory', 'Elegant Cory', 'Gastrodermus elegans', array['Elegant Corydoras']::text[], array['Corydoras elegans']::text[], '{}'::text[], 'Corydoras & Relatives', 'Callichthyidae', 'Gastrodermus', 'Freshwater', 72, 79, 6.0, 7.5, 2, 12, 2.0, 15, 'Peaceful', 'Schooling', 6, 'Mid-bottom', 'Omnivore', false, true, 'Beginner', 'Common', 'Egg-depositor', '5-8 years', 'Upper Amazon (Peru, Brazil, Colombia, Ecuador)', 'A small, slim cory with fine lines along its body that spends more time in open water than most corys.', 'Elegant corys belong to the small-cory group with the pygmy and salt and pepper corys, which moved to the genus Gastrodermus in 2024. They swim in loose groups above the bottom as often as they sift it, so they make a lively addition to a planted community. Keep six or more over soft sand to protect their barbels, feed sinking foods that actually reach them, and keep nitrates low. They often spawn on glass and plant leaves after a cool water change.', 'species', true),
  ('nanus-cory', 'Nanus Cory', 'Gastrodermus nanus', array['Nanus Corydoras']::text[], array['Corydoras nanus']::text[], '{}'::text[], 'Corydoras & Relatives', 'Callichthyidae', 'Gastrodermus', 'Freshwater', 72, 79, 6.0, 7.5, 2, 12, 1.8, 15, 'Peaceful', 'Schooling', 6, 'Mid-bottom', 'Omnivore', false, true, 'Intermediate', 'Common', 'Egg-depositor', '4-6 years', 'Suriname and French Guiana', 'A tiny, busy cory with a bold pattern of dark stripes and spots. Great for smaller community tanks.', 'Nanus corys stay under two inches and are among the most active corys, swimming in loose groups through the lower and middle water. They come from clear, flowing streams, so they appreciate good filtration, a little current and clean, well-oxygenated water. Keep six or more on sand and feed small sinking pellets, wafers and frozen foods. Like the other small corys, they moved to Gastrodermus in 2024.', 'species', true),
  ('bearded-cory', 'Bearded Cory', 'Scleromystax barbatus', array['Banded Cory', 'Barbatus Cory', 'Bearded Catfish']::text[], array['Corydoras barbatus']::text[], '{}'::text[], 'Corydoras & Relatives', 'Callichthyidae', 'Scleromystax', 'Freshwater', 64, 75, 6.0, 7.5, 2, 12, 4.0, 30, 'Peaceful', 'Schooling', 6, 'Bottom', 'Omnivore', false, true, 'Intermediate', 'Intermediate', 'Egg-depositor', '8-10 years', 'Coastal streams of southeastern Brazil', 'A large, cool-water cory from southern Brazil. Mature males grow bristly cheeks and a gold head stripe.', 'Bearded corys are one of the biggest and most striking cory-type catfish. Mature males develop the bristles along their cheeks that give them their name, plus a gold stripe over the head. They come from cooler coastal streams, so keep them around 68 to 74°F and don''t house them with fish that need high temperatures. Give them sand, steady current and a group of six or more, and feed sinking foods with some frozen bloodworm or brine shrimp.', 'species', true),
  ('sixray-cory', 'Sixray Cory', 'Aspidoras pauciradiatus', array['Six-ray Corydoras', 'Spotted Aspidoras', 'Aspidoras']::text[], '{}'::text[], '{}'::text[], 'Corydoras & Relatives', 'Callichthyidae', 'Aspidoras', 'Freshwater', 72, 80, 6.0, 7.5, 2, 10, 1.2, 10, 'Peaceful', 'Schooling', 8, 'Bottom', 'Omnivore', false, true, 'Intermediate', 'Intermediate', 'Egg-depositor', '3-5 years', 'Araguaia and Negro river basins, Brazil', 'A tiny cory relative, about an inch long, with a spotted body and a dark mark on the dorsal fin.', 'Aspidoras are close relatives of corys, smaller and slimmer, and this one stays around an inch. They feel safest in a big group, so keep eight or more in a mature, softer-water tank with fine sand and leaf litter to forage through. They are more sensitive to poor water than common corys, which makes them a good fit for a quiet nano or species tank. Feed small sinking foods, microworms and frozen baby brine shrimp.', 'species', true),
  ('flash-pleco', 'Flash Pleco', 'Panaqolus albivermis', array['L204 Pleco', 'Flash Panaque']::text[], '{}'::text[], array['L204']::text[], 'Plecos (L-number Catfish)', 'Loricariidae', 'Panaqolus', 'Freshwater', 75, 84, 6.0, 7.5, 2, 15, 4.5, 30, 'Peaceful', 'Solitary', null, 'Bottom', 'Herbivore', false, true, 'Intermediate', 'Common', 'Cave-spawner', '10-12 years', 'Upper Amazon, Peru', 'A small wood-eating pleco: black with bright white worm-like markings and orange-edged fins. L204.', 'Flash plecos stay under five inches, which makes them one of the better plecos for a planted community tank. Like the clown pleco they are wood eaters, so give them driftwood to rasp on, plus vegetables such as zucchini and a sinking wood-based or algae food. They''re peaceful with other fish but defend a favorite cave against their own kind. Males guard eggs in a snug cave and grow bristles on their fins as they mature.', 'species', true),
  ('cardinal-shrimp', 'Cardinal Shrimp', 'Caridina dennerli', array['Sulawesi Cardinal Shrimp', 'Cardinal Sulawesi Shrimp']::text[], '{}'::text[], '{}'::text[], 'Shrimp', 'Atyidae', 'Caridina', 'Freshwater', 80, 86, 7.5, 8.5, 4, 8, 1.0, 10, 'Peaceful', 'Colony', 10, 'Bottom', 'Omnivore', false, true, 'Expert', 'Expert', 'Livebearer', '1-2 years', 'Lake Matano, Sulawesi, Indonesia', 'A small red shrimp with white spots from Sulawesi''s ancient lakes. Beautiful, but only for experienced shrimp keepers.', 'Cardinal shrimp come from Lake Matano, a warm and extremely stable lake with alkaline water that is low in general hardness. They need a mature tank kept around 80 to 86°F with a pH near 8, no copper, and almost no change from week to week. Most keepers use RO water remineralized specifically for Sulawesi shrimp. Keep them on their own or with snails, since most fish will eat them, and give them porous rock covered in biofilm to graze. Females carry their eggs, and the young hatch as tiny copies of the adults.', 'species', true),
  ('tangerine-tiger-shrimp', 'Tangerine Tiger Shrimp', 'Caridina serrata', array['Tangerine Tiger', 'Orange Tiger Shrimp']::text[], '{}'::text[], '{}'::text[], 'Shrimp', 'Atyidae', 'Caridina', 'Freshwater', 68, 76, 6.0, 7.2, 4, 8, 1.2, 10, 'Peaceful', 'Colony', 10, 'Bottom', 'Omnivore', false, true, 'Intermediate', 'Intermediate', 'Livebearer', '1-2 years', 'Southern China; aquarium-bred line', 'A bright orange shrimp with fine dark stripes and black eyes. A Caridina, so it wants softer water than cherries.', 'Tangerine tigers are a Caridina, so they do best in the softer, steadier water that crystal and tiger shrimp like rather than the easy, harder water that suits cherry shrimp. Keep them in a mature planted tank with a stable temperature, no copper and a filter intake covered with sponge. They graze biofilm and algae and take shrimp pellets and blanched vegetables. They breed in the tank, and the young hatch fully formed; keep them away from other Caridina colors if you want the orange to stay clean.', 'species', true),
  ('trimac-cichlid', 'Trimac Cichlid', 'Amphilophus trimaculatus', array['Trimac', 'Three-spot Cichlid']::text[], array['Cichlasoma trimaculatum']::text[], '{}'::text[], 'Cichlids - New World', 'Cichlidae', 'Amphilophus', 'Freshwater', 75, 86, 7.0, 8.0, 8, 20, 14.0, 125, 'Aggressive', 'Pair', null, 'All', 'Omnivore', false, false, 'Advanced', 'Advanced', 'Substrate spawner', '10-15 years', 'Pacific slope of Central America (Mexico to El Salvador)', 'A big, bold Central American cichlid with three dark spots and a red-orange throat. Very aggressive.', 'Trimacs are one of the classic big Central American cichlids, prized for their color and personality and known for their temper. Adult males grow a nuchal hump and will fight anything they can reach, so plan on a large tank kept as a single fish, a bonded pair, or with other large, tough cichlids. They dig and rearrange everything, so use heavy rock and skip live plants. Feed quality cichlid pellets with some shrimp, krill and vegetables, and keep up with big water changes; they produce a lot of waste.', 'species', true),
  ('synspilum-cichlid', 'Synspilum Cichlid', 'Vieja melanura', array['Synspilum', 'Redhead Cichlid', 'Quetzal Cichlid']::text[], array['Vieja synspila', 'Cichlasoma synspilum']::text[], '{}'::text[], 'Cichlids - New World', 'Cichlidae', 'Vieja', 'Freshwater', 75, 86, 7.0, 8.0, 8, 20, 14.0, 125, 'Aggressive', 'Pair', null, 'All', 'Omnivore', false, false, 'Advanced', 'Advanced', 'Substrate spawner', '10-15 years', 'Usumacinta basin of Guatemala, Belize and Mexico', 'A large, colorful Central American cichlid with a red head and a rainbow body. Needs a big tank.', 'Synspilums grow into very large, very colorful fish: a red-orange head, a green and purple body and a dark blotch toward the tail. They are a little less vicious than some big cichlids but still territorial and powerful, so keep them in a large tank with other robust fish or as a pair. Their diet leans plant-based, so feed spirulina or vegetable pellets with some meaty foods. They will eat and uproot plants. The name Vieja synspila is now treated as the same species as Vieja melanura.', 'species', true),
  ('spotted-severum', 'Spotted Severum', 'Heros notatus', array['Notatus Severum']::text[], '{}'::text[], '{}'::text[], 'Cichlids - New World', 'Cichlidae', 'Heros', 'Freshwater', 78, 86, 5.5, 7.0, 2, 10, 10.0, 75, 'Semi-aggressive', 'Pairs', null, 'Mid', 'Omnivore', false, false, 'Intermediate', 'Intermediate', 'Substrate spawner', '10-15 years', 'Rio Negro, Brazil', 'A severum covered in dark spots and bars, from the blackwater Rio Negro.', 'Spotted severums are the Rio Negro cousin of the common green severum, with a pattern of dark spots and dashes over a golden body. They come from soft, acidic blackwater, so they look and do their best in warm, soft water with driftwood and some tannins. They''re calmer than many cichlids their size but grow large and will eat soft plants, so choose tough or floating plants. Feed a vegetable-rich cichlid pellet plus shrimp and greens.', 'species', true),
  ('port-acara', 'Port Acara', 'Cichlasoma portalegrense', array['Port Cichlid', 'Black Acara']::text[], '{}'::text[], '{}'::text[], 'Cichlids - New World', 'Cichlidae', 'Cichlasoma', 'Freshwater', 64, 82, 6.5, 8.0, 5, 20, 6.0, 40, 'Semi-aggressive', 'Pair', null, 'Mid-bottom', 'Omnivore', false, true, 'Beginner', 'Common', 'Substrate spawner', '8-10 years', 'Southern Brazil and Uruguay', 'A hardy, mid-sized South American cichlid that tolerates cooler water. A good first cichlid.', 'Port acaras are tough, adaptable cichlids that handle a wide temperature range, including cooler water than most tropical fish. They pair up and raise their fry openly, which makes them a great first breeding cichlid. Aside from guarding eggs they''re fairly calm and mix with similar-sized barbs, larger tetras and other mild cichlids. They dig a little, so anchor plants well or use sturdy ones, and feed a quality pellet with some frozen foods.', 'species', true),
  ('threadfin-acara', 'Threadfin Acara', 'Acarichthys heckelii', array['Heckel''s Acara', 'Heckel''s Threadfin Cichlid']::text[], '{}'::text[], '{}'::text[], 'Cichlids - New World', 'Cichlidae', 'Acarichthys', 'Freshwater', 77, 86, 5.0, 7.0, 1, 8, 8.0, 75, 'Semi-aggressive', 'Pair', null, 'Mid-bottom', 'Omnivore', false, false, 'Intermediate', 'Intermediate', 'Cave spawner', '8-12 years', 'Amazon basin (Brazil, Peru, Guyana)', 'A striking South American cichlid with long threads trailing from its dorsal fin. Digs burrows to breed.', 'Threadfin acaras are named for the long filaments that trail from the back of the dorsal fin on adults. They''re peaceful outside of breeding, but a pair digs a burrow under a rock or root and defends it hard. Give them soft, warm water, a deep sand bed, roots and stones to dig beneath, and room to claim a territory. Plants in the digging zone will be uprooted. Feed a varied diet of sinking pellets and frozen foods.', 'species', true),
  ('ellioti-cichlid', 'Ellioti Cichlid', 'Thorichthys ellioti', array['Ellioti', 'Spotted Firemouth']::text[], array['Cichlasoma ellioti']::text[], '{}'::text[], 'Cichlids - New World', 'Cichlidae', 'Thorichthys', 'Freshwater', 75, 82, 7.0, 8.0, 8, 20, 5.5, 40, 'Semi-aggressive', 'Pair', null, 'All', 'Omnivore', false, true, 'Intermediate', 'Common', 'Substrate spawner', '8-10 years', 'Papaloapan river basin, Mexico', 'A firemouth relative with a pale blue-spotted body and a red-edged throat. Moderately sized and manageable.', 'Ellioti are close cousins of the firemouth: similar shape and display, with turquoise spots across the body. Like firemouths they bluff more than they bite, flaring their gill covers to warn off rivals. A mated pair guards its territory when spawning, but otherwise they''re among the easier Central Americans to keep with sturdy community fish. Give them sand to sift, rocks and wood for territories, and a mixed diet of pellets and frozen food.', 'species', true),
  ('paraguay-eartheater', 'Paraguay Eartheater', 'Satanoperca pappaterra', array['Pappaterra Eartheater', 'Pappaterra']::text[], '{}'::text[], '{}'::text[], 'Cichlids - New World', 'Cichlidae', 'Satanoperca', 'Freshwater', 75, 84, 6.0, 7.5, 2, 12, 8.0, 75, 'Peaceful', 'Groups', 5, 'Bottom', 'Omnivore', false, false, 'Intermediate', 'Intermediate', 'Mouthbrooder', '8-10 years', 'Paraguay and upper Guaporé river basins', 'A peaceful eartheater that sifts sand all day. Best kept in a small group over fine sand.', 'Paraguay eartheaters spend their day taking mouthfuls of sand and filtering out food through their gills, so fine, smooth sand is a must; gravel injures them. They''re gentle for their size and do best in a group of five or more with other peaceful mid-sized fish. They''re sensitive to nitrate and poor water, so keep up with regular water changes and good filtration. Rooted plants will get dug up; use plants on wood and rock instead. Sinking pellets and small frozen foods suit them.', 'species', true),
  ('tropheus-duboisi', 'Tropheus Duboisi', 'Tropheus duboisi', array['Duboisi', 'White-spotted Cichlid', 'Blue-faced Duboisi']::text[], '{}'::text[], '{}'::text[], 'Cichlids - African Rift Lake', 'Cichlidae', 'Tropheus', 'Freshwater', 75, 81, 8.0, 9.0, 10, 20, 4.5, 55, 'Aggressive', 'Social', 10, 'Mid-bottom', 'Herbivore', false, false, 'Advanced', 'Advanced', 'Mouthbrooder', '8-10 years', 'Lake Tanganyika (northern shores)', 'A Tanganyikan grazer whose babies are black with white spots, growing into dark adults with a yellow or white band.', 'Young duboisi are black with bright white polka dots; adults turn dark with a blue face and a single yellow or white band. Like all Tropheus they eat algae and need a high-fiber, plant-based diet, because rich, meaty foods can cause deadly bloat. They''re quarrelsome with their own kind, so they''re kept in large groups of a dozen or more to spread the aggression, in hard, alkaline water with lots of rockwork. Duboisi are a bit milder than many Tropheus, which makes them a good first Tropheus for keepers ready for the commitment.', 'species', true),
  ('brevis-shell-dweller', 'Brevis Shell Dweller', 'Neolamprologus brevis', array['Brevis', 'Lamprologus brevis']::text[], array['Lamprologus brevis']::text[], '{}'::text[], 'Cichlids - African Rift Lake', 'Cichlidae', 'Neolamprologus', 'Freshwater', 75, 80, 7.8, 9.0, 10, 20, 2.0, 10, 'Semi-aggressive', 'Pairs', null, 'Bottom', 'Carnivore', false, true, 'Intermediate', 'Common', 'Cave-spawner', '6-10 years', 'Lake Tanganyika', 'A tiny Tanganyikan cichlid where a male and female share one snail shell. Fun for a small species tank.', 'Brevis are unusual among shell dwellers because a male and female often live in the same shell, retreating into it together when threatened. Give them a sandy bottom with plenty of empty escargot or similar shells, more shells than fish, in hard, alkaline water. They''re small but defend their shells fiercely, so keep them in their own tank or with other small Tanganyikans that don''t compete for shells. Feed small meaty foods like frozen brine shrimp, cyclops and quality micro pellets.', 'species', true),
  ('zebra-obliquidens', 'Zebra Obliquidens', 'Astatotilapia latifasciata', array['Obliquidens', 'Zebra Haplochromis']::text[], array['Haplochromis latifasciatus']::text[], '{}'::text[], 'Cichlids - African Rift Lake', 'Cichlidae', 'Astatotilapia', 'Freshwater', 72, 82, 7.5, 8.5, 8, 20, 4.5, 55, 'Aggressive', 'Harem', 3, 'Mid', 'Omnivore', false, true, 'Intermediate', 'Common', 'Mouthbrooder', '6-10 years', 'Lake Kyoga and Lake Nawampasa, Uganda', 'A small Victorian cichlid: males are yellow-gold with bold black bars and red fins. Rare in the wild, common in tanks.', 'Zebra obliquidens come from the Lake Victoria basin, where they''re now rare, and survive in the hobby thanks to aquarium breeding. Males are bright gold with heavy black bars and red on the fins; females are a plain silvery brown. Keep one male with several females, because males harass any lone female hard. They do fine in the same hard, alkaline setup as Malawi cichlids and eat almost anything, from flake to frozen foods. Females hold the eggs and fry in their mouths for about three weeks.', 'species', true),
  ('malawi-eyebiter', 'Malawi Eyebiter', 'Dimidiochromis compressiceps', array['Eyebiter', 'Compressiceps', 'Haplochromis compressiceps']::text[], array['Haplochromis compressiceps']::text[], '{}'::text[], 'Cichlids - African Rift Lake', 'Cichlidae', 'Dimidiochromis', 'Freshwater', 76, 82, 7.5, 8.5, 10, 20, 9.0, 125, 'Aggressive', 'Harem', 3, 'Mid', 'Carnivore', false, true, 'Advanced', 'Intermediate', 'Mouthbrooder', '8-10 years', 'Lake Malawi', 'A very thin, flat-bodied predator from Lake Malawi that hunts small fish head-on. Males turn metallic blue.', 'Malawi eyebiters have an extremely narrow body that lets them approach prey head-on almost unseen. The story that they bite the eyes of other fish comes from old reports and is rarely seen in tanks; they mostly eat small fish whole. Keep them with Malawi haps and peacocks too big to swallow, never with small mbuna fry or tiny tankmates. They need a long tank with open swimming space, hard alkaline water and a meaty diet of quality pellets and frozen foods. One male with several females works best.', 'species', true),
  ('azureus-cichlid', 'Azureus Cichlid', 'Copadichromis azureus', array['Azureus', 'Copadichromis Azureus']::text[], '{}'::text[], '{}'::text[], 'Cichlids - African Rift Lake', 'Cichlidae', 'Copadichromis', 'Freshwater', 76, 82, 7.5, 8.5, 10, 20, 6.0, 75, 'Semi-aggressive', 'Harem', 3, 'Middle', 'Omnivore', false, true, 'Intermediate', 'Common', 'Mouthbrooder', '8-10 years', 'Lake Malawi', 'A peaceful Malawi hap: males are deep electric blue, females silver. A calm choice for a hap and peacock tank.', 'Azureus are one of the calmer Malawi haps, feeding on tiny plankton in open water rather than picking fights over rocks. Males turn an intense blue with a pale edge on the dorsal fin, while females stay silver. Keep one male with several females alongside peacocks and other peaceful haps; aggressive mbuna will stress them. They need hard, alkaline water, open swimming room and small foods like quality micro pellets, krill and brine shrimp.', 'species', true),
  ('butterfly-splitfin', 'Butterfly Splitfin', 'Ameca splendens', array['Butterfly Goodeid', 'Ameca']::text[], '{}'::text[], '{}'::text[], 'Livebearers', 'Goodeidae', 'Ameca', 'Freshwater', 68, 79, 7.0, 8.0, 10, 20, 3.5, 30, 'Semi-aggressive', 'Groups', 6, 'All', 'Omnivore', true, true, 'Beginner', 'Common', 'Livebearer', '3-5 years', 'Río Ameca, Jalisco, Mexico', 'A Mexican livebearer nearly gone from the wild. Males flash gold and black with a yellow tail band.', 'Butterfly splitfins are goodeids, a family of Mexican livebearers that feed their young through a cord before birth, so babies are born large and ready to eat. The species has almost disappeared from its home river, which makes aquarium-bred stock important for its survival. They''re hardy and easy, but nippy, so avoid long-finned or slow tankmates. Keep a group with more females than males, give them hard water, room to swim and plenty of plant matter in the diet alongside flake and frozen foods.', 'species', true),
  ('red-tailed-splitfin', 'Red-tailed Splitfin', 'Xenotoca eiseni', array['Red-tailed Goodeid', 'Redtail Splitfin']::text[], '{}'::text[], '{}'::text[], 'Livebearers', 'Goodeidae', 'Xenotoca', 'Freshwater', 68, 79, 7.0, 8.0, 10, 25, 2.8, 30, 'Semi-aggressive', 'Groups', 6, 'All', 'Omnivore', true, true, 'Beginner', 'Common', 'Livebearer', '3-5 years', 'Western Mexico (Nayarit and Jalisco)', 'A hardy Mexican goodeid: males have a blue-green body and a bright orange-red tail section.', 'Red-tailed splitfins are one of the easiest goodeids and a great introduction to this threatened family of Mexican livebearers. Males are humped, with blue-green sides and a blazing orange-red rear. They''re active and can nip fins, so keep them with fast, sturdy fish or on their own. They like hard water, a little cooler than tropical tanks in winter, and a diet with plenty of vegetable matter. The fry are born large and can eat crushed flake from day one.', 'species', true),
  ('rainbow-characodon', 'Rainbow Characodon', 'Characodon lateralis', array['Rainbow Goodeid']::text[], '{}'::text[], '{}'::text[], 'Livebearers', 'Goodeidae', 'Characodon', 'Freshwater', 64, 75, 7.0, 8.0, 10, 20, 2.0, 20, 'Semi-aggressive', 'Groups', 6, 'All', 'Omnivore', false, true, 'Intermediate', 'Intermediate', 'Livebearer', '2-4 years', 'Durango, Mexico', 'A small, endangered goodeid from cool Mexican springs. Males show red and gold with black-edged fins.', 'Rainbow characodons come from a handful of cool spring pools in Durango and are endangered in the wild. They prefer cooler water than most tropical fish, with a warmer summer and a cooler winter rest that helps them breed. Males spar with each other, so give them plants and a group with extra females. They eat algae as well as small foods, so offer vegetable flake alongside frozen foods. Keeping and breeding pure, labeled populations is how hobbyists help this species.', 'species', true),
  ('tequila-splitfin', 'Tequila Splitfin', 'Zoogoneticus tequila', array['Tequila Fish', 'Tequila Goodeid']::text[], '{}'::text[], '{}'::text[], 'Livebearers', 'Goodeidae', 'Zoogoneticus', 'Freshwater', 68, 79, 7.0, 8.0, 10, 20, 2.0, 20, 'Peaceful', 'Groups', 6, 'Mid-bottom', 'Omnivore', false, true, 'Intermediate', 'Intermediate', 'Livebearer', '2-4 years', 'Río Teuchitlán, Jalisco, Mexico', 'A small goodeid that vanished from the wild, survived in aquariums, and was returned to its home river.', 'The tequila splitfin disappeared from its river in Jalisco and survived only in aquariums and research collections before being returned to the wild, which makes it a favorite of conservation-minded keepers. Males have a bright orange-yellow band on the tail. They''re fairly peaceful and do well in a planted species tank or with small, calm fish. Keep them slightly cooler than tropical fish, in hard water, and feed a mix of flake, frozen foods and vegetable matter.', 'species', true),
  ('merry-widow', 'Merry Widow', 'Phallichthys amates', array['Merry Widow Livebearer']::text[], '{}'::text[], '{}'::text[], 'Livebearers', 'Poeciliidae', 'Phallichthys', 'Freshwater', 72, 82, 7.0, 8.0, 8, 20, 2.5, 20, 'Peaceful', 'Groups', 6, 'Mid-top', 'Omnivore', false, true, 'Beginner', 'Common', 'Livebearer', '2-4 years', 'Atlantic slope of Guatemala and Honduras', 'A peaceful, easy livebearer with a black-edged dorsal fin. A calm alternative to guppies and mollies.', 'Merry widows are a classic, easy livebearer that''s less common in stores than guppies but just as hardy. Both sexes have a dark band along the edge of the dorsal fin, and males have an unusually long gonopodium. They''re peaceful, active and breed readily, so plan for fry or add some floating plants for them to hide in. Hard, slightly alkaline water and a varied diet of flake, vegetable foods and small frozen foods keep them healthy.', 'species', true),
  ('scarlet-livebearer', 'Scarlet Livebearer', 'Micropoecilia picta', array['Swamp Guppy', 'Painted Guppy', 'Poecilia picta']::text[], array['Poecilia picta']::text[], '{}'::text[], 'Livebearers', 'Poeciliidae', 'Micropoecilia', 'Freshwater', 75, 82, 7.0, 8.0, 10, 20, 1.6, 15, 'Peaceful', 'Groups', 6, 'Mid-top', 'Omnivore', false, true, 'Intermediate', 'Intermediate', 'Livebearer', '2-3 years', 'Coastal lowlands of northern South America and Trinidad', 'A small wild livebearer related to the guppy. Males of the red form are scarlet with a black-spotted pattern.', 'Scarlet livebearers are a small, wild-type relative of the guppy found in coastal swamps, where they handle fresh to slightly brackish water. Males come in several color forms, the best known a deep red with black markings, while females are plain. They''re more delicate than fancy guppies, so keep them in a mature, planted tank with hard water and calm, small tankmates. A pinch of aquarium salt is optional but they appreciate stable, clean water and small, varied foods.', 'species', true),
  ('duboulays-rainbowfish', 'Duboulay''s Rainbowfish', 'Melanotaenia duboulayi', array['Crimson-spotted Rainbowfish', 'Duboulay''s Rainbow']::text[], '{}'::text[], '{}'::text[], 'Rainbowfish', 'Melanotaeniidae', 'Melanotaenia', 'Freshwater', 68, 82, 6.5, 8.0, 8, 20, 4.0, 40, 'Peaceful', 'Schooling', 6, 'Mid-top', 'Omnivore', false, true, 'Beginner', 'Common', 'Egg-scatterer', '5-8 years', 'Coastal rivers of eastern Australia (New South Wales and Queensland)', 'A hardy Australian rainbowfish with a red spot on each gill cover and fins edged in red and black.', 'Duboulay''s rainbowfish are tough, adaptable and active, handling a wide temperature range including slightly cooler tanks. Each fish has a bright crimson spot on the gill cover, and males develop red and black edges on their fins as they mature. They need a long tank with open swimming room and a group of six or more, ideally with both sexes for the best color. Feed a varied diet of flake, small pellets and frozen foods; they spawn readily in fine-leaved plants or spawning mops.', 'species', true),
  ('axelrods-rainbowfish', 'Axelrod''s Rainbowfish', 'Melanotaenia herbertaxelrodi', array['Lake Tebera Rainbowfish', 'Lake Tebera Rainbow']::text[], '{}'::text[], '{}'::text[], 'Rainbowfish', 'Melanotaeniidae', 'Melanotaenia', 'Freshwater', 70, 79, 7.0, 8.0, 8, 20, 4.0, 40, 'Peaceful', 'Schooling', 6, 'Mid-top', 'Omnivore', false, true, 'Beginner', 'Common', 'Egg-scatterer', '5-8 years', 'Lake Tebera, Papua New Guinea', 'A golden-yellow rainbowfish from Lake Tebera with a dark stripe along its side. Peaceful and easy.', 'Axelrod''s rainbowfish come from Lake Tebera in the highlands of Papua New Guinea and are sometimes sold by that name. Adults are golden yellow with a dark band along the side, and males grow deeper-bodied and brighter with age. They''re peaceful, hardy and easy to breed, and they like hard, slightly alkaline water. Keep a group of six or more in a long tank with plants along the back and open water in front, and feed a varied diet.', 'species', true),
  ('lake-wanam-rainbowfish', 'Lake Wanam Rainbowfish', 'Glossolepis wanamensis', array['Lake Wanam Rainbow', 'Wanam Rainbowfish']::text[], '{}'::text[], '{}'::text[], 'Rainbowfish', 'Melanotaeniidae', 'Glossolepis', 'Freshwater', 75, 82, 7.0, 8.0, 10, 20, 4.0, 40, 'Peaceful', 'Schooling', 6, 'Mid-top', 'Omnivore', false, true, 'Intermediate', 'Intermediate', 'Egg-scatterer', '5-8 years', 'Lake Wanam, Papua New Guinea', 'A critically endangered rainbowfish: males turn blue-green with gold highlights. Kept alive by hobby breeders.', 'Lake Wanam rainbowfish are critically endangered in their single small lake in Papua New Guinea, threatened by introduced fish, and survive in the hobby through careful breeding. Males develop a high back and blue-green to gold coloring, while females stay silvery. Keep them like their cousin the red rainbowfish: a long, planted tank, hard and slightly alkaline water and a group with more females than males. Avoid mixing them with other Glossolepis, which can hybridize.', 'species', true),
  ('striatum-killifish', 'Striatum Killifish', 'Aphyosemion striatum', array['Red-striped Killifish', 'Five-lined Killifish', 'Striatum']::text[], '{}'::text[], '{}'::text[], 'Killifish', 'Nothobranchiidae', 'Aphyosemion', 'Freshwater', 68, 75, 6.0, 7.0, 2, 10, 2.0, 10, 'Peaceful', 'Pairs', null, 'Mid-top', 'Carnivore', false, true, 'Beginner', 'Common', 'Egg-layer', '2-3 years', 'Gabon and Equatorial Guinea', 'A small, easy killifish: males are blue-green with red stripes and a red-edged tail. A classic first killie.', 'Striatum are one of the easiest and most popular killifish, and a common first species for new killie keepers. Males are blue-green with rows of red dashes and red edges on the fins; females are plain brown. They prefer cooler, soft water and a tight lid, since they jump. Keep a male with two or three females in a small, planted tank with floating cover. They lay eggs in spawning mops or fine plants over several weeks, and the eggs hatch in water in about two weeks.', 'species', true),
  ('guenthers-nothobranchius', 'Guenther''s Notho', 'Nothobranchius guentheri', array['Guenther''s Killifish', 'Redtail Notho', 'Guentheri']::text[], '{}'::text[], '{}'::text[], 'Killifish', 'Nothobranchiidae', 'Nothobranchius', 'Freshwater', 72, 79, 6.5, 7.5, 4, 12, 2.0, 10, 'Semi-aggressive', 'Pairs', null, 'Middle', 'Carnivore', false, true, 'Intermediate', 'Intermediate', 'Egg-layer', '1 year', 'Seasonal pools of coastal Tanzania and Zanzibar', 'An annual killifish: males are scaled in blue-green and red with a bright red tail. Lives about a year.', 'Guenther''s notho is an annual killifish: in the wild it hatches when seasonal pools fill, grows fast, breeds and dies as the water dries up, leaving eggs buried in the mud. In the aquarium they live around a year, so keepers breed them continuously. Males are intensely colored and quarrelsome with each other, so keep one male with two or three females. They lay eggs in peat; the peat is dried for several weeks, then wetted to hatch the fry. Feed live and frozen foods like bloodworms and brine shrimp.', 'species', true),
  ('scarlet-betta', 'Scarlet Betta', 'Betta coccina', array['Wine Red Betta', 'Coccina Betta']::text[], '{}'::text[], '{}'::text[], 'Gouramis & Bettas', 'Osphronemidae', 'Betta', 'Freshwater', 76, 84, 4.0, 6.5, 0, 5, 2.0, 10, 'Peaceful', 'Pairs', null, 'Middle', 'Carnivore', false, true, 'Advanced', 'Advanced', 'Bubble-nester', '3-5 years', 'Peat swamp forests of Sumatra and peninsular Malaysia', 'A small wild betta, deep wine-red with a green spot on the side. Needs very soft, acidic blackwater.', 'Scarlet bettas are a wild betta from blackwater peat swamps, small and slender compared to the domestic betta. They''re deep wine red, and many show a shining green spot on each side. They need very soft, acidic water with a pH that can sit well below 6, which most keepers reach with RO water, peat and leaf litter. Keep a pair or a small group in a quiet, dim, heavily planted tank with a tight lid. Feed small live and frozen foods; many won''t take dry food at first.', 'species', true),
  ('leopard-bushfish', 'Leopard Bushfish', 'Ctenopoma acutirostre', array['Leopard Ctenopoma', 'Spotted Climbing Perch', 'Leopard Bush Fish']::text[], '{}'::text[], '{}'::text[], 'Oddballs & Specialty', 'Anabantidae', 'Ctenopoma', 'Freshwater', 73, 82, 6.0, 7.5, 4, 15, 6.0, 40, 'Semi-aggressive', 'Solitary', null, 'Mid-bottom', 'Carnivore', false, true, 'Intermediate', 'Intermediate', 'Egg-scatterer', '8-15 years', 'Congo River basin, Central Africa', 'A spotted African ambush predator that stalks its food slowly. Peaceful with fish too big to swallow.', 'Leopard bushfish hang still among roots and plants, then drift up on small fish and swallow them whole, so anything under about two inches is food. Keep them with peaceful fish too big to eat in a dim tank full of driftwood, plants and floating cover. They can breathe air at the surface, so leave a gap under the lid. Many refuse flake at first; start them on frozen bloodworms, earthworms or shrimp, and some learn to take sinking pellets. They''re shy, slow and long-lived.', 'species', true),
  ('orange-chromide', 'Orange Chromide', 'Pseudetroplus maculatus', array['Orange Chromide Cichlid']::text[], array['Etroplus maculatus']::text[], '{}'::text[], 'Oddballs & Specialty', 'Cichlidae', 'Pseudetroplus', 'Brackish', 72, 82, 7.5, 8.5, 10, 25, 3.5, 30, 'Semi-aggressive', 'Pairs', null, 'Mid-bottom', 'Omnivore', false, true, 'Intermediate', 'Intermediate', 'Substrate spawner', '5-8 years', 'Coastal lagoons and estuaries of southern India and Sri Lanka', 'One of the few cichlids from Asia: small, orange and black, for brackish or hard freshwater tanks.', 'Orange chromides are one of only a handful of cichlids native to Asia. In the wild they live in brackish lagoons; in the aquarium they do well in hard, alkaline freshwater or low-end brackish water around 1.002 to 1.005 specific gravity. Pairs clean a flat stone, guard the eggs and herd their fry like any substrate-spawning cichlid, and the young even feed on mucus from their parents'' skin. They''re feisty only when breeding and mix well with mollies, gobies and other brackish fish.', 'species', true),
  ('cobalt-blue-goby', 'Cobalt Blue Goby', 'Stiphodon semoni', array['Neon Blue Goby', 'Blue Neon Goby', 'Stiphodon Goby']::text[], '{}'::text[], '{}'::text[], 'Oddballs & Specialty', 'Gobiidae', 'Stiphodon', 'Freshwater', 72, 79, 6.5, 7.5, 4, 12, 1.5, 20, 'Peaceful', 'Groups', null, 'Bottom', 'Herbivore', false, true, 'Advanced', 'Intermediate', 'Egg-layer', '3-5 years', 'Fast hill streams of Indonesia and the western Pacific islands', 'A tiny stream goby: males glow electric blue with two black stripes. Grazes algae off rocks in fast water.', 'Cobalt blue gobies live in fast, clear hill streams and spend their time grazing algae and biofilm off rocks, so they need a mature tank with plenty of algae-covered stone, strong flow and lots of oxygen. Several Stiphodon species are sold under this name. Males flash brilliant blue and spar with each other, so keep one male with females or give a group plenty of rocky territory. Their larvae drift to the sea, so they aren''t bred in home aquariums. Supplement natural algae with algae wafers and fine foods.', 'species', true),
  ('purple-spotted-gudgeon', 'Purple Spotted Gudgeon', 'Mogurnda mogurnda', array['Northern Purple-spotted Gudgeon', 'Mogurnda']::text[], '{}'::text[], '{}'::text[], 'Oddballs & Specialty', 'Eleotridae', 'Mogurnda', 'Freshwater', 68, 82, 7.0, 8.0, 8, 20, 5.0, 40, 'Semi-aggressive', 'Pairs', null, 'Mid-bottom', 'Carnivore', false, true, 'Intermediate', 'Intermediate', 'Egg-depositor', '5-8 years', 'Northern Australia and New Guinea', 'A colorful Australian gudgeon covered in red, purple and orange spots. Will eat small fish.', 'Purple spotted gudgeons are covered in red, orange and purple spots, with bold lines through the cheek. They''re predators that will eat any fish or shrimp small enough to fit in their mouths, and males can be territorial, so keep them as a pair or with sturdy fish of similar size. Rocks, caves and wood give them territories to claim. Pairs lay eggs on a hard surface, and the male guards and fans them until they hatch. Feed meaty foods like frozen bloodworms, brine shrimp and quality pellets.', 'species', true),
  ('empire-gudgeon', 'Empire Gudgeon', 'Hypseleotris compressa', array['Empire Fish']::text[], '{}'::text[], '{}'::text[], 'Oddballs & Specialty', 'Eleotridae', 'Hypseleotris', 'Freshwater', 64, 82, 7.0, 8.0, 8, 20, 3.5, 30, 'Peaceful', 'Groups', 6, 'Middle', 'Carnivore', false, true, 'Intermediate', 'Intermediate', 'Egg-depositor', '4-6 years', 'Coastal rivers of Australia and southern New Guinea', 'A peaceful Australian gudgeon that swims in open water. Breeding males show red, blue and gold fins.', 'Empire gudgeons are unusual for gudgeons because they swim in loose groups in open water instead of sitting on the bottom. Breeding males turn brilliant, with red and gold fins edged in blue and a humped head. They''re peaceful with fish too big to eat but will take small shrimp and fry. Keep a group in a planted tank with hard, alkaline water and feed meaty foods like frozen brine shrimp, daphnia and small pellets. The eggs hatch in the tank, but the larvae need brackish water to survive, so home breeding is rare.', 'species', true),
  ('red-tail-dwarf-puffer', 'Red-tail Dwarf Puffer', 'Carinotetraodon irrubesco', array['Red-tailed Dwarf Puffer', 'Redtail Red-eye Puffer']::text[], '{}'::text[], '{}'::text[], 'Oddballs & Specialty', 'Tetraodontidae', 'Carinotetraodon', 'Freshwater', 75, 82, 6.0, 7.5, 2, 12, 2.5, 20, 'Semi-aggressive', 'Harem', 3, 'All', 'Carnivore', true, true, 'Intermediate', 'Intermediate', 'Egg-scatterer', '3-5 years', 'Sumatra and Borneo, Indonesia', 'A small freshwater puffer: males have a red-edged tail and bold markings. Best in a species tank.', 'Red-tail dwarf puffers are a slightly bigger relative of the pea puffer, fully freshwater and full of personality. Males show a red or orange edge on the tail and fins; females are mottled brown. Males fight each other, so keep one male with two or more females in a densely planted tank with lots of sight breaks. Like all puffers they nip and are best kept on their own. Feed live and frozen foods such as bloodworms and small snails, which also help wear down their beaks.', 'species', true),
  ('brown-ghost-knifefish', 'Brown Ghost Knifefish', 'Apteronotus leptorhynchus', array['Brown Ghost', 'Brownghost Knifefish']::text[], '{}'::text[], '{}'::text[], 'Oddballs & Specialty', 'Apteronotidae', 'Apteronotus', 'Freshwater', 73, 82, 6.0, 7.5, 2, 12, 12.0, 75, 'Semi-aggressive', 'Solitary', null, 'Bottom-mid', 'Carnivore', false, true, 'Advanced', 'Advanced', 'Egg-layer', '10-15 years', 'Amazon and Orinoco basins', 'A brown relative of the black ghost knifefish that swims by rippling one long fin. Nocturnal and electric.', 'Brown ghost knifefish move forward and backward with equal ease by rippling the long fin under their body, and they sense their surroundings with a weak electric field. They''re nocturnal and shy, so give them a tube or cave to hide in during the day and feed after lights out. They will eat small fish, so keep them with peaceful tankmates too large to swallow. Very clean water, soft sand and frozen foods like bloodworms and brine shrimp keep them healthy; they''re sensitive to medications, especially copper.', 'species', true),
  ('glass-knifefish', 'Glass Knifefish', 'Eigenmannia virescens', array['Green Knifefish', 'Transparent Knifefish']::text[], '{}'::text[], '{}'::text[], 'Oddballs & Specialty', 'Sternopygidae', 'Eigenmannia', 'Freshwater', 72, 82, 6.0, 7.5, 2, 12, 12.0, 75, 'Peaceful', 'Groups', 3, 'Bottom-mid', 'Carnivore', false, true, 'Advanced', 'Intermediate', 'Egg-layer', '10-15 years', 'Widespread across tropical South America', 'A semi-transparent, social knifefish that hovers in groups and communicates with weak electric signals.', 'Glass knifefish are a social, see-through knifefish that hover in groups among roots and plants, keeping in touch with each other through weak electric signals. They''re peaceful and do best in a small group in a long, dim tank with plenty of cover. They''re mostly active at dusk and at night, so feed some food after the lights go out. Keep tankmates calm and not too small, since they''ll eat tiny fish, and offer frozen bloodworms, brine shrimp and sinking pellets.', 'species', true)
) as v(slug, common_name, scientific_name, also_known_as, former_names, trade_codes, group_name, family, genus, water_type, temp_min_f, temp_max_f, ph_min, ph_max, gh_min, gh_max, max_size_in, min_tank_gal, temperament, social, min_group_size, swim_level, diet, fin_nipper, plant_safe, care_level, suitability, breeding_type, lifespan, origin, summary, body, entry_type, described)
where not exists (select 1 from public.species x where x.slug = v.slug);

update public.species
set also_known_as = array_append(coalesce(also_known_as, '{}'::text[]), 'Black Widow Tetra')
where slug = 'black-skirt-tetra' and not ('Black Widow Tetra' = any(coalesce(also_known_as, '{}'::text[])));

-- Check: the new profiles, by group.
select group_name, count(*) as added
from public.species
where slug in ('yellow-phantom-tetra', 'jellybean-tetra', 'hockeystick-pencilfish', 'one-lined-pencilfish', 'elegant-cory', 'nanus-cory', 'bearded-cory', 'sixray-cory', 'flash-pleco', 'cardinal-shrimp', 'tangerine-tiger-shrimp', 'trimac-cichlid', 'synspilum-cichlid', 'spotted-severum', 'port-acara', 'threadfin-acara', 'ellioti-cichlid', 'paraguay-eartheater', 'tropheus-duboisi', 'brevis-shell-dweller', 'zebra-obliquidens', 'malawi-eyebiter', 'azureus-cichlid', 'butterfly-splitfin', 'red-tailed-splitfin', 'rainbow-characodon', 'tequila-splitfin', 'merry-widow', 'scarlet-livebearer', 'duboulays-rainbowfish', 'axelrods-rainbowfish', 'lake-wanam-rainbowfish', 'striatum-killifish', 'guenthers-nothobranchius', 'scarlet-betta', 'leopard-bushfish', 'orange-chromide', 'cobalt-blue-goby', 'purple-spotted-gudgeon', 'empire-gudgeon', 'red-tail-dwarf-puffer', 'brown-ghost-knifefish', 'glass-knifefish')
group by group_name
order by group_name;
